//! 🎟️ Genuine original authority birth records actual Arc attempts independently of physical receipt.
use semio_framework_job_context::*;
use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
use semio_framework_value_testing_allocator as _;
use semio_framework_value::ValueError;
use std::mem::MaybeUninit;
use semio_framework_job_payload::JobPayloadAuthority;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn birth(output:&mut Option<JobPayloadAuthority>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
 let mut actual=None;let turn=JobPayloadAuthority::admit(OperationId(7543),Generation(3),cx.retained_grant(),&mut actual);let result=match turn.result{Ok(Some((owner,p)))=>{*output=Some(owner);Ok(RetainedCloneStep::Complete(p))},Ok(None)=>Ok(RetainedCloneStep::Progress(Default::default())),Err(error)=>Err(error)};let step=receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work:turn.work})?;Ok(matches!(step,RetainedCloneStep::Complete(_)))
}
#[test]
fn genuine_payload_authority_raw_null_keeps_stock_and_admits_exact_ledger_on_retry(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let s=&row["stock"];let bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..bank};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7543),Generation(3),bank,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());let mut output=None;
 caller.turn(RetainedCloneGrant{maximum_items:0,..q},|cx|{let work=cx.original_work_units_spent();let(result,heap)=observe(||birth(&mut output,cx));assert!(!result?);assert!(output.is_none());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.original_work_units_spent()-work,u128::from(row["deniedWork"].as_u64().unwrap()));Ok(())}).unwrap();
 caller.turn(q,|cx|{let work=cx.original_work_units_spent();let before=cx.retained_progress();let((result,attempts),heap)=observe(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||birth(&mut output,cx)));assert_eq!(attempts,1);assert!(result.is_err());assert!(output.is_none());assert_eq!(cx.retained_progress().copied_items-before.copied_items,row["nullItems"].as_u64().unwrap()as usize);assert_eq!(cx.original_work_units_spent()-work,u128::from(row["nullWork"].as_u64().unwrap()));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())}).unwrap();
 caller.turn(q,|cx|{let work=cx.original_work_units_spent();let before=cx.retained_progress();let(result,heap)=observe(||birth(&mut output,cx));assert!(result?);assert_eq!(cx.retained_progress().copied_items-before.copied_items,row["successItems"].as_u64().unwrap()as usize);assert_eq!(cx.original_work_units_spent()-work,u128::from(row["successWork"].as_u64().unwrap()));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(JobPayloadAuthority::admission_demand().capacity_bytes,0));Ok(())}).unwrap();
 let owner=output.as_mut().unwrap();let ledger=owner.original().unwrap();assert_eq!(serde_json::json!([ledger.operation.0,ledger.generation.0]),serde_json::json!([row["operation"],row["generation"]]));
 for _ in 0..16{if owner.terminal_is_empty(){break;}caller.turn(q,|cx|{let demand=owner.retirement_demands();let(result,heap)=observe(||close_original_retained_effect_step(cx,demand,|effect|owner.close_step(effect).result));let p=result?.progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));Ok(())}).unwrap();}assert!(owner.terminal_is_empty());let(_,heap)=observe(||drop(output.take()));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.retire(bank);
}

#[test]
fn genuine_payload_builder_normal_metadata_posts_full_work_once_and_cached_zero(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let law=&row["metadataWork"];let s=&row["stock"];let bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..bank};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7543),Generation(3),bank,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());let mut builder=RetainedPayloadBuilder::new(JobPayloadStream::CommitOutput);
 caller.turn(RetainedCloneGrant{maximum_items:0,..q},|cx|{let turn=builder.advance_initialization(cx);assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap() as u128);assert_eq!(turn.result.unwrap().progress(),Default::default());assert!(builder.original().is_none());Ok(())}).unwrap();
 let mut initialized_turns=0;for turn in 0..law["maximumInitializationTurns"].as_u64().unwrap(){if builder.is_initialized(){break}caller.turn(q,|cx|cx.with_original_work_loan(1,cx.deadline_us(),|cx|{let work=cx.original_work_units_spent();let(outcome,heap)=observe(||builder.advance_initialization(cx));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(outcome.work,1);let step=receive_original_retained_work(cx,outcome)?;assert_eq!(step.progress().copied_bytes,law["copyBytes"].as_u64().unwrap()as usize);assert_eq!(cx.original_work_units_spent()-work,1);assert_eq!(matches!(step,RetainedCloneStep::Complete(_)),turn+1==law["initializationTurns"].as_u64().unwrap());Ok(())})).unwrap();initialized_turns+=1;}assert_eq!(initialized_turns,law["initializationTurns"].as_u64().unwrap());
 assert!(builder.is_initialized());assert_eq!(builder.original().unwrap().page_count(),law["livePages"].as_u64().unwrap()as usize);assert_eq!(JOB_PAYLOAD_OPERATION_PAGES,law["maximumPages"].as_u64().unwrap()as usize);
 caller.turn(q,|cx|{let turn=builder.advance_initialization(cx);assert_eq!(turn.work,law["cachedWork"].as_u64().unwrap() as u128);assert_eq!(turn.result.unwrap().progress(),Default::default());let work=cx.original_work_units_spent();let outcome=builder.seal(cx);assert_eq!(outcome.work,law["sealWork"].as_u64().unwrap() as u128);receive_original_retained_work(cx,outcome)?;assert_eq!(cx.original_work_units_spent()-work,u128::from(law["sealWork"].as_u64().unwrap()));Ok(())}).unwrap();
 caller.turn(q,|cx|{let work=cx.original_work_units_spent();let turn=builder.seal(cx);assert_eq!(turn.work,law["cachedWork"].as_u64().unwrap() as u128);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(cx.original_work_units_spent(),work);Ok(())}).unwrap();assert_eq!(serde_json::json!([builder.original().unwrap().page_count(),builder.published().unwrap().page_count()]),serde_json::json!([law["livePages"],0]));
 for _ in 0..16{if builder.terminal_is_empty(){break;}caller.turn(q,|cx|{close_original_retained_effect_step(cx,builder.retirement_demands()?,|effect|builder.close_step(effect).result)?;Ok(())}).unwrap();}assert!(builder.terminal_is_empty());drop(builder);caller.retire(bank);
}

#[test]
fn genuine_payload_page_counter_null_retry_and_publication_keep_one_original_wallet(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let law=&row["pageWork"];let s=&row["stock"];let bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let extent=law["extent"].as_u64().unwrap()as usize;let q=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:extent,..bank};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7543),Generation(3),bank,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());let mut builder=RetainedPayloadBuilder::new(JobPayloadStream::CommitOutput);
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if builder.is_initialized(){break;}caller.turn(q,|cx|{let turn=builder.advance_initialization(cx);receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();}assert!(builder.is_initialized());let data=law["text"].as_str().unwrap().as_bytes();let mut cursor=0;
 caller.turn(q,|cx|cx.with_original_work_loan(1,cx.deadline_us(),|cx|{let(outcome,heap)=observe(||builder.append_original(cx,data,&mut cursor));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(outcome.work,law["actualWork"][0].as_u64().unwrap() as u128);receive_original_retained_work(cx,outcome)?;assert_eq!(cursor,0);assert_eq!(JobPayloadStep::payload_ledger(cx).process_share_bytes(),0);Ok(())})).unwrap();
 caller.turn(q,|cx|cx.with_original_work_loan(1,cx.deadline_us(),|cx|{let(outcome,heap)=observe(||builder.append_original(cx,data,&mut cursor));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(outcome.work,law["actualWork"][1].as_u64().unwrap() as u128);receive_original_retained_work(cx,outcome)?;assert_eq!(cursor,0);assert_eq!(JobPayloadStep::payload_ledger(cx).process_share_bytes(),extent);Ok(())})).unwrap();
 caller.turn(q,|cx|cx.with_original_work_loan(1,cx.deadline_us(),|cx|{let before=cx.retained_progress();let((outcome,attempts),heap)=observe(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||builder.append_original(cx,data,&mut cursor)));assert_eq!(attempts,1);assert_eq!(outcome.work,law["nullWork"].as_u64().unwrap() as u128);assert!(outcome.result.is_err());assert!(receive_original_retained_work(cx,outcome).is_err());assert_eq!(cx.retained_progress().copied_items-before.copied_items,law["nullItems"].as_u64().unwrap()as usize);assert_eq!(cursor,0);assert_eq!(JobPayloadStep::payload_ledger(cx).process_share_bytes(),extent);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())})).unwrap();
 for stage in 2..5{caller.turn(q,|cx|cx.with_original_work_loan(1,cx.deadline_us(),|cx|{let work=cx.original_work_units_spent();let(outcome,heap)=observe(||builder.append_original(cx,data,&mut cursor));assert_eq!(outcome.work,law["actualWork"][stage].as_u64().unwrap() as u128);let step=receive_original_retained_work(cx,outcome)?;assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_eq!(heap.requested_bytes,if stage==2{extent}else{0});assert_eq!(cx.original_work_units_spent()-work,1);if stage<4{assert_eq!(cursor,0);assert_eq!(step.progress().copied_bytes,0);}else{assert_eq!(cursor,data.len());assert_eq!(step.progress().copied_bytes,data.len());}Ok(())})).unwrap();}
 caller.turn(q,|cx|{let turn=builder.seal(cx);receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();let actual=builder.published().unwrap().single_page().unwrap();assert_eq!(serde_json::to_value(std::str::from_utf8(actual).unwrap()).unwrap(),law["text"]);
 for _ in 0..law["maximumTurns"].as_u64().unwrap(){if builder.terminal_is_empty(){break;}caller.turn(q,|cx|{let demand=builder.retirement_demands()?;let(result,heap)=observe(||close_original_retained_effect_step(cx,demand,|effect|builder.close_step(effect).result));let p=result?.progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));Ok(())}).unwrap();}assert!(builder.terminal_is_empty());drop(builder);caller.retire(bank);
}

struct PartialOriginalSource;
impl semio_framework_job_payload::JobPayloadStagedSource for PartialOriginalSource{
 fn byte_len(&self)->usize{2}
 fn copy_byte_demand(&self)->Result<usize,JobPayloadAdmissionFault>{Ok(2)}
 fn depth_demand(&self)->Result<usize,JobPayloadAdmissionFault>{Ok(1)}
 fn write_bytes(&self,target:&mut[MaybeUninit<u8>])->semio_framework_value::RetainedWorkOutcome<semio_framework_job_payload::JobPayloadWriteProgress,semio_framework_job_payload::JobPayloadWriteFailure>{
  target[0].write(65);semio_framework_value::RetainedWorkOutcome{result:Err(semio_framework_job_payload::JobPayloadWriteFailure{fault:JobPayloadAdmissionFault::StreamBytes,initialized_bytes:1,progress:RetainedCloneProgress{copied_items:1,copied_bytes:1,..Default::default()}}),work:1}
 }
}
#[test]
fn genuine_partial_source_error_keeps_initialized_page_and_posts_actual_work_before_error(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let law=&row["sourceFailureWork"];let s=&row["stock"];let bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..bank};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7543),Generation(3),bank,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());let mut builder=RetainedPayloadBuilder::new(JobPayloadStream::Fault);
 for _ in 0..512{if builder.is_initialized(){break;}caller.turn(q,|cx|{let turn=builder.advance_initialization(cx);receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();}for _ in 0..8{if builder.staged_page_len().is_some(){break;}caller.turn(q,|cx|{let turn=builder.begin_staged_page_funded(cx);receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();}let pointer=builder.staged_backing_identity();assert!(pointer.is_some());
 caller.turn(q,|cx|cx.with_original_work_loan(1,cx.deadline_us(),|cx|{let work=cx.original_work_units_spent();let(turn,heap)=observe(||builder.write_staged_source_funded(cx,&PartialOriginalSource));let failure=receive_original_retained_work(cx,turn).unwrap_err();assert_eq!(failure.retained_progress().copied_bytes,law["errorCopyBytes"].as_u64().unwrap()as usize);assert_eq!(failure.retained_progress().copied_items,law["errorItems"].as_u64().unwrap()as usize);assert_eq!(cx.original_work_units_spent()-work,u128::from(law["errorWork"].as_u64().unwrap()));assert_eq!(builder.staged_page_len(),Some(law["errorWrittenBytes"].as_u64().unwrap()as usize));assert_eq!(builder.staged_backing_identity(),pointer);assert_eq!(builder.published().is_some(),law["published"].as_bool().unwrap());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())})).unwrap();
 for _ in 0..512{if builder.terminal_is_empty(){break;}caller.turn(q,|cx|{let demand=builder.retirement_demands()?;let(result,heap)=observe(||close_original_retained_effect_step(cx,demand,|effect|builder.close_step(effect).result));let p=result?.progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));Ok(())}).unwrap();}assert!(builder.terminal_is_empty());drop(builder);caller.retire(bank);
}

#[test]
fn genuine_boxed_builder_null_then_admitted_output_keeps_actual_work_and_paid_backing(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let law=&row["boxedWork"];let s=&row["stock"];let bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..bank};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7543),Generation(3),bank,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());let mut output=None;
 caller.turn(RetainedCloneGrant{maximum_items:0,..q},|cx|{let turn=RetainedPayloadBuilder::admit_boxed(JobPayloadStream::Fault,&mut output,cx);assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap() as u128);assert_eq!(turn.result.unwrap().progress(),Default::default());assert!(output.is_none());Ok(())}).unwrap();
 caller.turn(q,|cx|{let work=cx.original_work_units_spent();let((turn,attempts),heap)=observe(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||RetainedPayloadBuilder::admit_boxed(JobPayloadStream::Fault,&mut output,cx)));assert_eq!(attempts,1);assert_eq!(turn.work,law["nullWork"].as_u64().unwrap() as u128);assert!(receive_original_retained_work(cx,turn).is_err());assert_eq!(cx.original_work_units_spent()-work,u128::from(law["nullWork"].as_u64().unwrap()));assert!(output.is_none());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())}).unwrap();
 caller.turn(q,|cx|{let work=cx.original_work_units_spent();let(turn,heap)=observe(||RetainedPayloadBuilder::admit_boxed(JobPayloadStream::Fault,&mut output,cx));assert!(output.is_some());assert_eq!(turn.work,law["successWork"].as_u64().unwrap() as u128);let p=receive_original_retained_work(cx,turn)?.progress();assert_eq!(cx.original_work_units_spent()-work,u128::from(law["successWork"].as_u64().unwrap()));assert_eq!(p.copied_bytes,law["copyBytes"].as_u64().unwrap()as usize);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,0));Ok(())}).unwrap();assert!(output.as_ref().unwrap().terminal_is_empty());
 caller.turn(q,|cx|{let demand=RetainedPayloadBuilder::boxed_release_demands();let(result,heap)=observe(||close_original_retained_step(cx,demand,|_|{drop(output.take());semio_framework_value::RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:demand.release_bytes,..Default::default()})),work:1}}));let p=result?.progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,p.released_bytes));Ok(())}).unwrap();assert!(output.is_none());caller.retire(bank);
}

#[test]
fn genuine_incoming_page_keeps_both_exact_backings_and_closes_each_only_when_paid(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();let law=&row["incomingWork"];let s=&row["stock"];let bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let q=RetainedCloneGrant{maximum_items:1,..bank};let extent=law["extent"].as_u64().unwrap()as usize;let mut caller=OriginalJobFixtureCaller::admit(OperationId(7543),Generation(3),bank,||Some(0),s["deadlineUs"].as_u64().unwrap(),s["fuel"].as_u64().unwrap());let mut builder=RetainedPayloadBuilder::new(JobPayloadStream::Fault);
 for _ in 0..512{if builder.is_initialized(){break;}caller.turn(q,|cx|{let turn=builder.advance_initialization(cx);receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();}for _ in 0..8{if builder.staged_page_len().is_some(){break;}caller.turn(q,|cx|{let turn=builder.begin_staged_page_funded(cx);receive_original_retained_work(cx,turn)?;Ok(())}).unwrap();}let staged=builder.staged_backing_identity();assert!(staged.is_some());let mut source=None;
 caller.turn(q,|cx|{let turn=JobPayloadPageSource::admit(extent,cx.retained_grant());let result=turn.result.map(|value|{let(page,p)=value.unwrap();source=Some(page);RetainedCloneStep::Complete(p)});receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work:turn.work})?;Ok(())}).unwrap();let incoming=source.as_ref().unwrap().backing_identity();
 caller.turn(RetainedCloneGrant{maximum_items:0,..q},|cx|{let(turn,heap)=observe(||builder.accept_original_page(&mut source,cx));assert_eq!(turn.work,law["deniedWork"].as_u64().unwrap() as u128);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(source.as_ref().unwrap().backing_identity(),incoming);assert_eq!(builder.incoming_backing_identity(),None);assert_eq!(builder.staged_backing_identity(),staged);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())}).unwrap();
 caller.turn(q,|cx|{let(turn,heap)=observe(||builder.accept_original_page(&mut source,cx));assert!(source.is_none());assert_eq!(turn.work,law["acceptWork"].as_u64().unwrap() as u128);let p=receive_original_retained_work(cx,turn)?.progress();assert_eq!(p.copied_bytes,law["copyBytes"].as_u64().unwrap()as usize);assert_eq!(builder.incoming_backing_identity(),Some(incoming));assert_eq!(builder.staged_backing_identity(),staged);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));Ok(())}).unwrap();
 caller.turn(q,|cx|{let turn=builder.accept_original_page(&mut source,cx);assert_eq!(turn.work,law["blockedWork"].as_u64().unwrap() as u128);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(builder.incoming_backing_identity(),Some(incoming));assert_eq!(builder.staged_backing_identity(),staged);Ok(())}).unwrap();caller.cancel().cancel_now();
 caller.turn(q,|cx|{let(denied,_)=cx.with_original_effect(RetainedCloneGrant{maximum_release_bytes:extent-1,..q},|_,effect|builder.close_step(effect))?.unwrap();assert_eq!(denied.work,law["deniedWork"].as_u64().unwrap() as u128);assert_eq!(denied.result.unwrap().progress(),Default::default());assert_eq!(builder.incoming_backing_identity(),Some(incoming));assert_eq!(builder.staged_backing_identity(),staged);Ok(())}).unwrap();let mut released=0;
 for _ in 0..512{if builder.terminal_is_empty(){break;}caller.turn(q,|cx|{let demand=builder.retirement_demands()?;let(result,heap)=observe(||close_original_retained_effect_step(cx,demand,|effect|builder.close_step(effect).result));let p=result?.progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));released+=p.released_bytes;Ok(())}).unwrap();}assert!(builder.terminal_is_empty());assert_eq!(released,law["releaseBytes"].as_u64().unwrap()as usize);drop(builder);caller.retire(bank);
}
